'use strict';
const $ = s => document.querySelector(s);
const categories = ['Montanha','Estrada','Gravel','Urbanas','Elétricas','BMX','Dobráveis','Infantis','Triatlo','Cicloturismo','Carga','Fixas','Fat bikes','Tandem','Reclinadas','Pista','Handbikes'];
const photos = {road:'photo-1485965120184-e220f721d03e',mtb:'photo-1532298229144-0ec0c57515c7',city:'photo-1571068316344-75bc76f77890',detail:'photo-1511994298241-608e28f14fde',ride:'photo-1544191696-15693072a251'};
const img = (key,w=700) => `assets/${(photos[key] || photos.detail).replace("photo-", "")}.jpg`;
// Catálogo conceitual. As fotografias representam o universo do ciclismo;
// não correspondem às especificações ou aos modelos fictícios abaixo.
const bikes = [
 ['Terra 01','Montanha',8490,'Alumínio','mtb','29″','Dianteira'],['Summit Carbon','Montanha',22990,'Carbono','mtb','29″','Integral'],['Aero Road','Estrada',15990,'Carbono','road','700c','Rígida'],['Endurance 02','Estrada',11990,'Alumínio','road','700c','Rígida'],['Beyond Gravel','Gravel',13490,'Carbono','detail','700c','Rígida'],['Nomad Adventure','Gravel',9490,'Alumínio','detail','700c','Rígida'],['City Flow','Urbanas',3290,'Alumínio','city','700c','Rígida'],['Volt Urban','Elétricas',12490,'Alumínio','city','700c','Dianteira'],['Volt Trail','Elétricas',24990,'Alumínio','mtb','29″','Integral'],['Air BMX','BMX',2890,'Aço','detail','20″','Rígida'],['Fold Go','Dobráveis',3790,'Alumínio','city','20″','Rígida'],['Little Explorer','Infantis',1290,'Alumínio','city','20″','Rígida'],['Velocity TT','Triatlo',28990,'Carbono','road','700c','Rígida'],['Horizon Touring','Cicloturismo',7990,'Aço','detail','700c','Rígida'],['Cargo Life','Carga',14490,'Alumínio','city','26″','Rígida'],['Fixed One','Fixas',2490,'Aço','road','700c','Rígida'],['Wild Fat','Fat bikes',6990,'Alumínio','mtb','26″','Dianteira'],['Together Duo','Tandem',10990,'Alumínio','city','700c','Rígida'],['Relax Journey','Reclinadas',16490,'Alumínio','detail','26″','Rígida'],['Velodrome','Pista',17990,'Carbono','road','700c','Rígida'],['Freedom Hand','Handbikes',19490,'Alumínio','detail','26″','Rígida']
];
const products = bikes.map((p,i)=>({id:i+1,name:p[0],category:p[1],price:p[2],material:p[3],photo:p[4],wheel:p[5],suspension:p[6],dept:'Bicicletas',sizes:p[1]==='Infantis'?['Único']:['P','M','G'],tag:i<3?'ESCOLHA VELO':p[1]==='Elétricas'?'ASSISTÊNCIA ELÉTRICA':'',description:`Um conceito de ${p[1].toLowerCase()} para explorar o seu próximo caminho. Modelo fictício criado para esta experiência de portfólio.`}));
[
 ['Capacete Orbit','Capacetes',349,'Policarbonato'],['Luz Path','Iluminação',189,'Alumínio'],['Garrafa Move','Acessórios',79,'Policarbonato'],['Sapatilha Pace','Sapatilhas',549,'Têxtil'],['Jersey Motion','Camisas',289,'Têxtil'],['Bretelle Endurance','Bretelles',399,'Têxtil'],['Jaqueta Wind','Jaquetas',459,'Têxtil'],['Luvas Grip','Luvas',129,'Têxtil']
].forEach((p,i)=>products.push({id:22+i,name:p[0],category:p[1],price:p[2],material:p[3],photo:'detail',dept:i<4?'Equipamentos':'Vestuário',sizes:i===1||i===2?['Único']:['P','M','G','GG'],tag:'COMPLETE SEU PEDAL',description:'Produto conceitual para acompanhar o seu movimento. Imagem editorial de ciclismo; produto e especificações ilustrativos.'}));
const money = n => n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
let dept='Bicicletas', category='', comparison=new Set(), toastTimer;
let cart=[];
try { const saved=JSON.parse(localStorage.getItem('velo-cart')||'[]'); if(Array.isArray(saved)) cart=saved.filter(x=>Number.isInteger(x.id)&&products.some(p=>p.id===x.id)&&typeof x.size==='string'&&products.find(p=>p.id===x.id).sizes.includes(x.size)&&Number.isInteger(x.qty)&&x.qty>0&&x.qty<=99); } catch {}
const find = id => products.find(p=>p.id===Number(id));
function notify(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,3300)}
function saveCart(){try{localStorage.setItem('velo-cart',JSON.stringify(cart))}catch{}$('#cartCount').textContent=cart.reduce((sum,x)=>sum+x.qty,0)}
function closeMenu(){$('#mega').hidden=true;$('#bikeMenu').setAttribute('aria-expanded','false');$('#mobileMenu').setAttribute('aria-expanded','false')}
function setDepartment(value,cat=''){dept=value;category=cat;$('#query').value='';$('#price').value='60000';$('#material').value='';$('#sizeFilter').value='';closeMenu();renderCategories();renderProducts();document.querySelectorAll('.departments button').forEach(b=>b.classList.toggle('active',b.dataset.dept===dept))}
function renderCategories(){const list=dept==='Bicicletas'?categories:[...new Set(products.filter(p=>p.dept===dept).map(p=>p.category))];$('#categoryChips').innerHTML=['',...list].map(c=>`<button data-category="${c}" class="${c===category?'active':''}" aria-pressed="${c===category}">${c||'Ver tudo'}</button>`).join('')}
function renderProducts(){const search=$('#query').value.trim().toLocaleLowerCase('pt-BR');const price=Number($('#price').value);$('#priceLabel').textContent=money(price);let list=products.filter(p=>p.dept===dept&&(!category||p.category===category)&&p.price<=price&&(!$('#material').value||p.material===$('#material').value)&&(!$('#sizeFilter').value||p.sizes.includes($('#sizeFilter').value))&&`${p.name} ${p.category} ${p.material}`.toLocaleLowerCase('pt-BR').includes(search));const sort=$('#sort').value;if(sort==='asc')list.sort((a,b)=>a.price-b.price);if(sort==='desc')list.sort((a,b)=>b.price-a.price);if(sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));$('#resultCount').textContent=`${list.length} produto${list.length===1?'':'s'}`;$('#products').innerHTML=list.length?list.map(p=>`<article class="product-card"><div class="product-image"><button data-product="${p.id}" aria-label="Ver detalhes de ${p.name}"><img src="${img(p.photo)}" alt="Fotografia ilustrativa de ciclismo para ${p.name}" loading="lazy"></button>${p.tag?`<span class="tag">${p.tag}</span>`:''}</div><div class="product-info"><p class="product-category">${p.category} / ${p.material}</p><button class="product-name" data-product="${p.id}">${p.name}</button><p class="product-price">${money(p.price)} <small>preço ilustrativo</small></p><div class="product-end"><span class="color-dots" aria-hidden="true"><i></i><i></i><i></i></span>${p.dept==='Bicicletas'?`<label class="compare-check"><input type="checkbox" data-compare="${p.id}" ${comparison.has(p.id)?'checked':''}>Comparar</label>`:'<span class="product-category">CONCEITO VELO</span>'}</div></div></article>`).join(''):'<div class="empty"><h3>Nenhum produto por aqui.</h3><p>Tente outra busca ou limpe os filtros para explorar mais caminhos.</p><button class="button dark" id="emptyReset">Limpar filtros ↗</button></div>'}
function openProduct(id){const p=find(id);if(!p)return;$('#productDetail').innerHTML=`<div class="detail-grid"><img src="${img(p.photo,1000)}" alt="Imagem editorial ilustrativa para ${p.name}"><div class="detail-copy"><p class="eyebrow">${p.category} / CONCEITO VELO</p><h2>${p.name}</h2><p>${p.description}</p><p class="price">${money(p.price)}</p><label for="productSize">Escolha seu tamanho</label><select id="productSize">${p.sizes.map(s=>`<option>${s}</option>`).join('')}</select><dl><dt>Material</dt><dd>${p.material}</dd>${p.wheel?`<dt>Aro</dt><dd>${p.wheel}</dd><dt>Suspensão</dt><dd>${p.suspension}</dd>`:''}<dt>Uso</dt><dd>${p.category}</dd></dl><button class="button dark" data-add="${p.id}">Adicionar à sacola <span>↗</span></button><p class="demo-note">Modelo fictício. Fotografia editorial ilustrativa, sem correspondência exata com o produto.</p></div></div>`;$('#productDialog').showModal()}
function renderCart(){$('#cartItems').innerHTML=cart.length?cart.map((item,i)=>{const p=find(item.id);return `<article class="cart-row"><img src="${img(p.photo,300)}" alt="Imagem ilustrativa de ${p.name}"><div><h3>${p.name}</h3><p>Tamanho ${item.size} · ${money(p.price)}</p><div class="quantity"><button data-qty="${i}" data-delta="-1" aria-label="Diminuir quantidade de ${p.name}">−</button><span>${item.qty}</span><button data-qty="${i}" data-delta="1" aria-label="Aumentar quantidade de ${p.name}">+</button><button class="remove" data-remove="${i}">Remover</button></div></div></article>`}).join(''):'<div class="empty"><h3>Seu próximo caminho começa aqui.</h3><p>A sacola está vazia. Explore o catálogo e escolha seus favoritos.</p><button class="button dark" data-continue>Explorar catálogo ↗</button></div>';$('#cartFooter').innerHTML=cart.length?`<div class="cart-total"><span>Subtotal</span><strong>${money(cart.reduce((s,x)=>s+find(x.id).price*x.qty,0))}</strong></div><button class="button dark" id="demoCheckout">Concluir experiência <span>↗</span></button><p class="demo-note">Não há cobrança, processamento de pagamento ou envio.</p>`:''}
function renderCompare(){const chosen=[...comparison].map(find);$('#compareBar').hidden=!chosen.length;$('#compareCount').textContent=`${chosen.length} de 3 selecionadas`;document.querySelectorAll('[data-compare]').forEach(el=>el.checked=comparison.has(Number(el.dataset.compare)))}
function openCompare(){if(comparison.size<2){notify('Selecione pelo menos duas bicicletas para comparar.');return}const ps=[...comparison].map(find);const rows=[['Modalidade','category'],['Preço ilustrativo','price'],['Material','material'],['Aro','wheel'],['Suspensão','suspension']];$('#compareContent').innerHTML=`<div class="compare-scroll"><table class="compare-table"><thead><tr><th>Seu próximo pedal</th>${ps.map(p=>`<td><img src="${img(p.photo,300)}" alt="Imagem ilustrativa de ${p.name}"><strong>${p.name}</strong></td>`).join('')}</tr></thead><tbody>${rows.map(([title,key])=>`<tr><th>${title}</th>${ps.map(p=>`<td>${key==='price'?money(p[key]):p[key]}</td>`).join('')}</tr>`).join('')}<tr><th>Explore</th>${ps.map(p=>`<td><button data-product="${p.id}">Ver produto ↗</button></td>`).join('')}</tr></tbody></table></div><p class="demo-note">Especificações conceituais. Fotografias ilustrativas.</p>`;$('#compareDialog').showModal()}
$('#menuCategories').innerHTML=categories.map(c=>`<a href="#catalogo" data-cat="${c}">${c} ↗</a>`).join('')+'<a href="#catalogo" data-dept="Equipamentos">Equipamentos ↗</a><a href="#catalogo" data-dept="Vestuário">Vestuário ↗</a>';
document.addEventListener('click',e=>{const t=e.target.closest('button,a');if(!t)return;if(t.dataset.dept){setDepartment(t.dataset.dept);return}if(t.dataset.cat){setDepartment('Bicicletas',t.dataset.cat);return}if(t.hasAttribute('data-category')){category=t.dataset.category;renderCategories();renderProducts();return}if(t.dataset.product){if($('#compareDialog').open)$('#compareDialog').close();openProduct(t.dataset.product);return}if(t.hasAttribute('data-close')){t.closest('dialog').close();return}if(t.dataset.add){const id=Number(t.dataset.add),size=$('#productSize').value;const item=cart.find(x=>x.id===id&&x.size===size);if(item&&item.qty>=99){notify('Limite de 99 unidades por item.');return}if(item)item.qty++;else cart.push({id,size,qty:1});saveCart();$('#productDialog').close();renderCart();$('#cartDialog').showModal();return}if(t.hasAttribute('data-qty')){const i=Number(t.dataset.qty);cart[i].qty+=Number(t.dataset.delta);if(cart[i].qty<=0)cart.splice(i,1);else cart[i].qty=Math.min(cart[i].qty,99);saveCart();renderCart();return}if(t.hasAttribute('data-remove')){cart.splice(Number(t.dataset.remove),1);saveCart();renderCart();return}if(t.hasAttribute('data-continue')){$('#cartDialog').close();$('#catalogo').scrollIntoView();return}if(t.id==='demoCheckout'){cart=[];saveCart();renderCart();$('#cartItems').innerHTML='<div class="empty"><h3>Seu caminho está só começando. ↗</h3><p>Experiência concluída! Esta é uma loja de portfólio: nenhum pedido, cobrança ou envio foi realizado.</p><button class="button dark" data-continue>Continuar explorando ↗</button></div>';return}if(t.id==='emptyReset')resetFilters()});
document.addEventListener('change',e=>{if(e.target.dataset.compare){const id=Number(e.target.dataset.compare);if(e.target.checked){if(comparison.size>=3){e.target.checked=false;notify('Você pode comparar até três bicicletas de cada vez.');return}comparison.add(id)}else comparison.delete(id);renderCompare()}});
function resetFilters(){setDepartment(dept);$('#sort').value='featured';renderProducts()}
$('#clearFilters').onclick=resetFilters;
for(const id of ['query','price','material','sizeFilter','sort'])$('#'+id).addEventListener(id==='query'||id==='price'?'input':'change',renderProducts);
function toggleMenu(){const open=$('#mega').hidden;$('#mega').hidden=!open;$('#bikeMenu').setAttribute('aria-expanded',String(open));$('#mobileMenu').setAttribute('aria-expanded',String(open))}
$('#bikeMenu').onclick=toggleMenu;$('#mobileMenu').onclick=toggleMenu;
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});document.addEventListener('click',e=>{if(!e.target.closest('header,.mega'))closeMenu()});
$('#filterToggle').onclick=()=>{const hidden=!$('#filters').hidden;$('#filters').hidden=hidden;$('.catalog-layout').classList.toggle('no-filters',hidden);$('#filterToggle').setAttribute('aria-expanded',String(!hidden))};
$('#searchButton').onclick=()=>{$('#filters').hidden=false;$('.catalog-layout').classList.remove('no-filters');$('#filterToggle').setAttribute('aria-expanded','true');$('#catalogo').scrollIntoView();setTimeout(()=>$('#query').focus({preventScroll:true}),350)};
$('#cartButton').onclick=()=>{renderCart();$('#cartDialog').showModal()};$('#compareOpen').onclick=openCompare;$('#compareClear').onclick=()=>{comparison.clear();renderCompare()};
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
saveCart();renderCategories();renderProducts();
